```yaml
name: Approve Workflows
on:
  pull_request_target:
    types:
      - labeled
      - synchronize
  workflow_dispatch: {}

jobs:
  approve:
    runs-on: ubuntu-latest
    steps:
      - name: Check if PR is from a first-time contributor
        id: check_contributor
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { owner, repo } = context.repo;
            const prNumber = context.payload.pull_request.number;
            const creator = context.payload.pull_request.user.login;

            // Get all PRs by this creator
            const prsQuery = `
              query($owner: String!, $repo: String!, $creator: String!) {
                repository(owner: $owner, name: $repo) {
                  pullRequests(first: 100, states: OPEN, author: $creator) {
                    nodes {
                      number
                      title
                    }
                  }
                }
              }
            `;

            const prsResponse = await github.graphql(prsQuery, {
              owner,
              repo,
              creator
            });

            const prCount = prsResponse.repository.pullRequests.nodes.length;

            // If this is the first PR, it's a first-time contributor
            const isFirstTimeContributor = prCount <= 1;

            // Check if ok-to-test label exists
            const hasOkToTestLabel = context.payload.pull_request.labels.some(label => label.name === 'ok-to-test');

            // Set outputs
            core.setOutput('is_first_time_contributor', isFirstTimeContributor);
            core.setOutput('has_ok_to_test_label', hasOkToTestLabel);
            core.setOutput('pr_count', prCount);

      - name: Auto-approve workflow runs
        if: |
          (steps.check_contributor.outputs.is_first_time_contributor == 'false') ||
          (steps.check_contributor.outputs.has_ok_to_test_label == 'true')
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { owner, repo } = context.repo;
            const prNumber = context.payload.pull_request.number;

            // Get current workflow run ID
            const runId = context.runId;

            // Approve the workflow run
            try {
              await github.rest.actions.approveWorkflowRun({
                owner,
                repo,
                run_id: runId
              });
              console.log(`Approved workflow run ${runId}`);
            } catch (error) {
              console.error(`Failed to approve workflow run ${runId}:`, error);
              throw error;
            }

      - name: Log decision
        if: |
          (steps.check_contributor.outputs.is_first_time_contributor == 'true') &&
          (steps.check_contributor.outputs.has_ok_to_test_label == 'false')
        run: |
          echo "First-time contributor without 'ok-to-test' label - workflow will require manual approval"
